import { useState, useEffect, useCallback } from 'react';
import { collection, doc, getDocs, getDoc, setDoc, deleteDoc, query, orderBy, serverTimestamp, writeBatch, where, updateDoc, increment } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';

export interface ArchiveEntity {
    id: string;
    name: string;
    description?: string;
    createdAt: any;
    itemCount: number;
    // For UI ease, we might want to preview images, but that's complex to maintain.
}

export interface SavedItemEntity {
    id: string; // Composite ID usually: `${type}_${itemId}` or just auto-id
    itemId: string;
    placeId?: string; // Critical for navigation
    type: 'place' | 'review' | 'group' | 'list';
    name: string;
    photoUrl?: string; // Snapshot for display
    savedAt: any;
    subtitle?: string; // e.g., Place name for a review
    route: string; // Pre-calculated route to navigate to
}

export const useArchives = () => {
    const { user } = useAuth();
    const [archives, setArchives] = useState<ArchiveEntity[]>([]);
    const [loading, setLoading] = useState(false);

    // Fetch user's archives
    const fetchArchives = useCallback(async () => {
        if (!user) return;
        setLoading(true);
        try {
            const q = query(collection(db, 'users', user.uid, 'archives'), orderBy('createdAt', 'desc'));
            const snap = await getDocs(q);
            const data = snap.docs.map(d => ({ id: d.id, ...d.data() })) as ArchiveEntity[];

            // If no archives exist, create a default "Guardados"
            if (data.length === 0) {
                const defaultRef = doc(collection(db, 'users', user.uid, 'archives'));
                await setDoc(defaultRef, {
                    name: "Guardados",
                    description: "Elementos guardados por defecto",
                    createdAt: serverTimestamp(),
                    itemCount: 0
                });
                data.push({ id: defaultRef.id, name: "Guardados", createdAt: new Date(), itemCount: 0 });
            }

            setArchives(data);
        } catch (error) {
            console.error("Error fetching archives:", error);
        } finally {
            setLoading(false);
        }
    }, [user]);

    // Create a new archive
    const createArchive = async (name: string) => {
        if (!user) return null;
        try {
            const newRef = doc(collection(db, 'users', user.uid, 'archives'));
            await setDoc(newRef, {
                name,
                createdAt: serverTimestamp(),
                itemCount: 0
            });
            await fetchArchives(); // Refresh
            return newRef.id;
        } catch (error) {
            console.error("Error creating archive:", error);
            throw error;
        }
    };

    // Delete an archive
    const deleteArchive = async (archiveId: string) => {
        if (!user) return;
        try {
            await deleteDoc(doc(db, 'users', user.uid, 'archives', archiveId));
            // Note: This leaves subcollection items orphaned in Firestore unless we use a Cloud Function to clean them up.
            // For now, this is acceptable for the MVP or we can strictly delete items if we had them loaded.
            // Client-side cleanup of subcollections is expensive.
            await fetchArchives(); // Refresh
        } catch (error) {
            console.error("Error deleting archive:", error);
            throw error;
        }
    };

    // Check if item is saved in any archive (returns list of archive IDs)
    const checkItemSavedStatus = async (itemId: string) => {
        if (!user) return [];
        // This is tricky in Firestore subcollections. 
        // We'd need to query ALL archives' subcollections, which is expensive (collectionGroup query restricted by user path issue).
        // ALTERNATIVE: Simplify. A separate root collection `saved_items` per user or just query archives if count is low.
        // DESIGN CHOICE: iterate archives for now. User won't have 100 archives.

        const savedArchiveIds: string[] = [];

        // Parallel check (Optimization: Could denormalize "saved_in" array on client if we tracked it differently)
        // For MVP: We check against the `archives` state if populated, or fetch logic.
        // Actually, to make "isSaved" efficient, usually we have a `users/{uid}/saved_refs/{itemId}` document.
        // Let's implement that pattern for global "Is Saved?" checks.

        // However, the prompt implies "Membership in specific folder".
        // Let's iterate `archives` and check `archives/{id}/items/{itemId}` exists.

        // Improved Approach: `collectionGroup(db, 'items')` with `where('itemId', '==', itemId)` AND filter client side by parent path?
        // No, `users/{uid}/archives/{aid}/items`.

        // Let's stick to simple Iteration for now, assuming < 10 archives.
        await Promise.all(archives.map(async (arch) => {
            const docRef = doc(db, 'users', user.uid, 'archives', arch.id, 'items', itemId);
            const snap = await getDoc(docRef);
            if (snap.exists()) savedArchiveIds.push(arch.id);
        }));

        return savedArchiveIds;
    };

    // Toggle Item in Archive
    const toggleItemInArchive = async (archiveId: string, item: SavedItemEntity, isAdding: boolean) => {
        if (!user) return;

        const itemRef = doc(db, 'users', user.uid, 'archives', archiveId, 'items', item.itemId); // Use itemId as docId to ensure uniqueness per archive
        const archiveRef = doc(db, 'users', user.uid, 'archives', archiveId);

        try {
            if (isAdding) {
                await setDoc(itemRef, { ...item, savedAt: serverTimestamp() });
                await updateDoc(archiveRef, { itemCount: increment(1) });
            } else {
                await deleteDoc(itemRef);
                await updateDoc(archiveRef, { itemCount: increment(-1) });
            }
        } catch (e) {
            console.error("Error toggling item:", e);
        }
    };

    return {
        archives,
        loading,
        fetchArchives,
        createArchive,
        deleteArchive,
        checkItemSavedStatus,
        toggleItemInArchive
    };
};

import { useState, useEffect } from 'react';
import { collection, query, getDocs } from 'firebase/firestore';
import { db } from '../firebase';

export interface Badge {
    id: string;
    name: string;
    descriptionPublic: string;
    descriptionLogic?: string;
    imageUrl?: string;
    active: boolean;
    type?: string;
    threshold?: number;
}

export const useBadges = () => {
    const [badges, setBadges] = useState<Badge[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchBadges = async () => {
            try {
                const q = query(collection(db, 'badges'));
                const snap = await getDocs(q);
                const fetchedBadges = snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Badge));
                setBadges(fetchedBadges);
            } catch (err: any) {
                console.error("Error fetching badges:", err);
                setError(err.message);
            } finally {
                setLoading(false);
            }
        };

        fetchBadges();
    }, []);

    const getBadge = (id: string) => badges.find(b => b.id === id);

    return { badges, loading, error, getBadge };
};

import { useState, useEffect } from 'react';
import { collection, getDocs, query, where, limit, doc, getDoc, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';
import type { ReviewEntity } from './useListDetails';

export const useFollowingFeed = () => {
    const { user } = useAuth();
    const [reviews, setReviews] = useState<ReviewEntity[]>([]);
    const [loading, setLoading] = useState(true);
    const [empty, setEmpty] = useState(false);

    useEffect(() => {
        if (!user) {
            setLoading(false);
            setReviews([]);
            return;
        }

        const fetchFeed = async () => {
            setLoading(true);
            try {
                // 1. Get Following IDs
                const followingRef = collection(db, 'users', user.uid, 'following');
                const followingSnap = await getDocs(followingRef);

                const followedIds = followingSnap.docs.map(doc => doc.id);

                if (followedIds.length === 0) {
                    setEmpty(true);
                    setReviews([]);
                    setLoading(false);
                    return;
                }

                // 2. Build a bounded set of readable list IDs and query subcollections directly.
                const [publicListsSnap, followingListsSnap, ownListsSnap] = await Promise.all([
                    getDocs(query(collection(db, 'lists'), where('isPublic', '==', true), limit(50))),
                    getDocs(query(collection(db, 'users', user.uid, 'followingLists'), limit(50))),
                    getDocs(query(collection(db, 'lists'), where('userId', '==', user.uid), limit(30)))
                ]);

                const candidateListIds = Array.from(new Set([
                    ...publicListsSnap.docs.map((d) => d.id),
                    ...followingListsSnap.docs.map((d) => d.id),
                    ...ownListsSnap.docs.map((d) => d.id)
                ])).slice(0, 60);

                const followedSet = new Set(followedIds);
                const reviewsPerList = await Promise.all(candidateListIds.map(async (listId) => {
                    try {
                        const listReviewsSnap = await getDocs(
                            query(collection(db, 'lists', listId, 'reviews'), orderBy('createdAt', 'desc'), limit(10))
                        );
                        return listReviewsSnap.docs
                            .map((reviewDoc) => ({
                                id: reviewDoc.id,
                                ...(reviewDoc.data() as any),
                                listId
                            } as ReviewEntity))
                            .filter((review) => {
                                const authorId = review.userId || (review as any).authorId;
                                return typeof authorId === 'string' && followedSet.has(authorId);
                            });
                    } catch (error: any) {
                        if (error?.code !== 'permission-denied') {
                            console.warn(`Error loading following reviews for list ${listId}`, error);
                        }
                        return [] as ReviewEntity[];
                    }
                }));

                const dedupMap = new Map<string, ReviewEntity>();
                for (const listReviews of reviewsPerList) {
                    for (const review of listReviews) {
                        dedupMap.set(`${review.listId || 'unknown'}:${review.id}`, review);
                    }
                }
                let allReviews = Array.from(dedupMap.values());

                // 4. Enrich Data (Fetch Users, Lists, and Places)
                const userIds = Array.from(new Set(allReviews.map(r => r.userId).filter(Boolean))) as string[];
                const listIds = Array.from(new Set(allReviews.map(r => r.listId).filter(Boolean))) as string[];
                const placeIds = Array.from(new Set(allReviews.map(r => r.placeId).filter(Boolean))) as string[];

                const [userSnaps, listSnaps, placeSnaps] = await Promise.all([
                    Promise.all(userIds.map(async (uid) => {
                        try {
                            return await getDoc(doc(db, 'users', uid));
                        } catch {
                            return null;
                        }
                    })),
                    Promise.all(listIds.map(async (lid) => {
                        try {
                            return await getDoc(doc(db, 'lists', lid));
                        } catch {
                            return null;
                        }
                    })),
                    Promise.all(placeIds.map(async (pid) => {
                        try {
                            return await getDoc(doc(db, 'places', pid));
                        } catch {
                            return null;
                        }
                    }))
                ]);

                const userMap = new Map(userSnaps.filter((s): s is NonNullable<typeof s> => !!s).map(s => [s.id, s.data() as any]));
                const listMap = new Map(listSnaps.filter((s): s is NonNullable<typeof s> => !!s).map(s => [s.id, s.data() as any]));
                const placeMap = new Map(placeSnaps.filter((s): s is NonNullable<typeof s> => !!s).map(s => [s.id, s.data() as any]));

                const enrichedReviews = allReviews.map(r => {
                    const u = r.userId ? userMap.get(r.userId) : null;
                    const l = r.listId ? listMap.get(r.listId) : null;
                    const p = r.placeId ? placeMap.get(r.placeId) : null;
                    return {
                        ...r,
                        authorName: u?.displayName || u?.username || r.authorName || 'Usuario',
                        authorPhoto: u?.photoUrl || r.authorPhoto,
                        criteriaDefinition: l?.criteriaDefinition || r.criteriaDefinition,
                        listName: l?.name || r.listName,
                        placeName: p?.name || r.placeName || 'Lugar desconocido'
                    };
                });

                // 3. Sort by createdAt desc (Moved after enrichment or before, doesn't matter, but let's keep logic)
                enrichedReviews.sort((a: any, b: any) => {
                    const tA = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
                    const tB = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
                    return tB - tA;
                });

                setReviews(enrichedReviews.slice(0, 50)); // Global limit
                setEmpty(enrichedReviews.length === 0);

            } catch (error) {
                console.error("Error fetching following feed:", error);
                setReviews([]);
            } finally {
                setLoading(false);
            }
        };

        fetchFeed();
    }, [user]);

    return { reviews, loading, empty };
};

import { useState, useEffect } from 'react';
import { doc, getDoc, setDoc, deleteDoc, updateDoc, increment, serverTimestamp } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';

export const useLike = (listId: string, initialCount: number = 0) => {
    const { user } = useAuth();
    const [isLiked, setIsLiked] = useState(false);
    const [likeCount, setLikeCount] = useState(initialCount);
    const [loading, setLoading] = useState(false);

    // Check if user has liked (followed) this list
    useEffect(() => {
        if (!user || !listId) {
            setIsLiked(false);
            return;
        }

        const checkLike = async () => {
            try {
                // Now using 'followingLists' as the source of truth for "Liking/Following"
                const docRef = doc(db, 'users', user.uid, 'followingLists', listId);
                const docSnap = await getDoc(docRef);

                if (docSnap.exists()) {
                    setIsLiked(true);
                }
            } catch (err: any) {
                if (err.code !== 'permission-denied') {
                    console.error("Error checking like status:", err);
                }
            }
        };

        checkLike();
    }, [listId, user]);

    const toggleLike = async () => {
        if (!user) return; // Or show login prompt

        // Optimistic update
        const previousState = isLiked;

        setIsLiked(!isLiked);
        setLikeCount(prev => isLiked ? prev - 1 : prev + 1);
        setLoading(true);

        try {
            const listRef = doc(db, 'lists', listId); // Needed only for reading data if falling back
            const followingListRef = doc(db, 'users', user.uid, 'followingLists', listId);

            // Backend Trigger 'onListFollowingWrite' in 'social.js' handles:
            // 1. Updating user.followingListsCount
            // 2. Updating list.likes and list.followersCount

            if (previousState) {
                // Unlike (Unfollow)
                await deleteDoc(followingListRef);
            } else {
                // Like (Follow)
                // We need to fetch list basics to store in the following doc for the profile feed
                // Ideally this data is passed in, but fetching here is safe (public list read)
                const listSnap = await getDoc(listRef);
                const listData = listSnap.data() || {};

                await setDoc(followingListRef, {
                    listId,
                    name: listData.name || 'Lista sin nombre',
                    photoUrl: listData.photoUrl || '',
                    itemCount: listData.itemCount || 0,
                    ownerName: listData.ownerName || listData.authorName || 'Anónimo',
                    followedAt: serverTimestamp()
                });
            }
        } catch (err) {
            console.error("Error toggling like:", err);
            // Revert on error
            setIsLiked(previousState);
            setLikeCount(prev => previousState ? prev + 1 : prev - 1);
        } finally {
            setLoading(false);
        }
    };

    return { isLiked, likeCount, toggleLike, loading };
};

import { useState, useEffect } from 'react';
import { doc, getDoc, query, where, orderBy, getDocs, Timestamp, collection } from 'firebase/firestore';
import { db } from '../firebase';
import { type ListEntity } from './useLists';

export interface ReviewEntity {
    id: string;
    listId: string;
    placeId: string; // The "Item" being reviewed
    itemName: string; // Redundant but useful
    comment: string;
    overallRating: number;
    photoUrl?: string;
    userId: string;
    authorName?: string;
    authorPhoto?: string;
    createdAt: Timestamp;
    updatedAt?: Timestamp; // Added field
    // Dynamic criteria scores
    scores?: Record<string, number>;
    lat?: number;
    lng?: number;
    // Aggregates
    reactionCounts?: {
        like?: number;
        love?: number;
        useful?: number;
        dislike?: number;
    };
    commentCount?: number; // Added for UI
    // Enriched Data
    listName?: string;
    placeName?: string;
    placeAddress?: string;
    placeCity?: string;
    placeMainImage?: string;
    placeAverageRating?: number;
    criteriaDefinition?: Record<string, { label: string; min?: number; max?: number; step?: number; ponderable?: boolean }>;
    authorId?: string; // Legacy compatibility
    tags?: string[];
    userTags?: string[];
}

const toMillis = (value: any): number => {
    if (!value) return 0;
    if (typeof value?.toMillis === 'function') return value.toMillis();
    if (typeof value?.seconds === 'number') return value.seconds * 1000;
    return 0;
};

export const useListDetails = (listId: string | undefined) => {
    const [list, setList] = useState<ListEntity | null>(null);
    const [reviews, setReviews] = useState<ReviewEntity[]>([]);
    const [sublists, setSublists] = useState<ListEntity[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (!listId) {
            setLoading(false);
            return;
        }

        const fetchData = async () => {
            setLoading(true);
            try {
                // 1. Fetch List Metadata
                const listRef = doc(db, 'lists', listId);
                const listSnap = await getDoc(listRef);

                if (!listSnap.exists()) {
                    setError('Lista no encontrada');
                    setLoading(false);
                    return;
                }

                setList({ id: listSnap.id, ...listSnap.data() } as ListEntity);
                const listData = listSnap.data();

                // 1.1 Fetch Parent List Name if applicable
                if (listData?.parentListId) {
                    try {
                        const parentSnap = await getDoc(doc(db, 'lists', listData.parentListId));
                        if (parentSnap.exists()) {
                            (listData as any).parentListName = parentSnap.data().name;
                            // Update the state as well
                            setList(prev => prev ? ({ ...prev, parentListName: parentSnap.data().name }) : null);
                        }
                    } catch (e) {
                        console.warn("Failed to fetch parent list name", e);
                    }
                }

                // 2. Fetch List Items (Reviews)
                let rawReviews: ReviewEntity[] = [];

                if (listData?.parentListId) {
                    // Sublist case: read from parent list subcollection and filter by sublistId.
                    const q = query(collection(db, 'lists', listData.parentListId, 'reviews'), where('sublistId', '==', listId));
                    const snap = await getDocs(q);
                    rawReviews = snap.docs.map(d => ({ id: d.id, ...d.data() })) as ReviewEntity[];
                } else {
                    // Main list case: read directly from list subcollection.
                    const q = query(collection(db, 'lists', listId, 'reviews'), orderBy('createdAt', 'desc'));
                    const snap = await getDocs(q);
                    rawReviews = snap.docs
                        .map(d => ({ id: d.id, ...d.data() }))
                        .filter((r: any) => r.visibility !== 'private') as ReviewEntity[];
                }

                rawReviews.sort((a: any, b: any) => toMillis(b.createdAt) - toMillis(a.createdAt));

                // --- Enrich Data ---
                // We need Places and Users. Lists are not needed as we have the parent list.
                const placeIds = [...new Set(rawReviews.map(r => r.placeId).filter((id): id is string => !!id))];
                const userIds = [...new Set(rawReviews.map(r => r.userId || r.authorId).filter((id): id is string => !!id))];

                const fetchDocsMap = async (collectionName: string, ids: string[]) => {
                    if (!ids.length) return {};
                    const map: Record<string, any> = {};
                    await Promise.all(ids.map(async (id) => {
                        try {
                            const snap = await getDoc(doc(db, collectionName, id));
                            if (snap.exists()) map[id] = snap.data();
                        } catch (e: any) {
                            if (e.code !== 'permission-denied') {
                                console.warn(`Failed to fetch ${collectionName} ${id}`, e);
                            }
                        }
                    }));
                    return map;
                };

                const [placesMap, usersMap] = await Promise.all([
                    fetchDocsMap('places', placeIds),
                    fetchDocsMap('users', userIds)
                ]);

                const enrichedReviews = rawReviews.map(review => {
                    const place = review.placeId ? placesMap[review.placeId] : null;
                    const userId = review.userId || review.authorId;
                    const user = userId ? usersMap[userId] : null;

                    // Support legacy establishmentName if place fetch fails or is missing
                    const legacyReview = review as any;
                    const listData = listSnap.data() as ListEntity;

                    // Address Fallback Logic
                    // 1. place.address (string)
                    // 2. place.city (string)
                    // 3. place.address_components (array) -> find locality
                    let city = place?.city;
                    if (!city && place?.addressComponents) {
                        const locality = place.addressComponents.find((c: any) => c.types.includes('locality'));
                        if (locality) city = locality.long_name;
                    }

                    return {
                        ...review,
                        // Attach List Context
                        listName: listData.name,
                        criteriaDefinition: listData.criteriaDefinition,

                        // Attach Enriched Data
                        placeName: place?.name || legacyReview.establishmentName || review.placeName,
                        placeAddress: place?.address || place?.formattedAddress || place?.vicinity,
                        placeCity: city,

                        placeMainImage: place?.mainImageUrl || place?.photos?.[0],
                        placeAverageRating: place?.rating || place?.avgScore,

                        authorName: user?.displayName || user?.name || user?.username || review.authorName,
                        authorPhoto: user?.photoUrl || user?.photoURL || review.authorPhoto,

                        // Attach Location Data (Map Support)
                        lat: place?.location?.latitude || legacyReview.lat || review.lat,
                        lng: place?.location?.longitude || legacyReview.lng || review.lng,

                        // Tags
                        tags: legacyReview.userTags || review.tags || [],
                    };
                });

                setReviews(enrichedReviews);

                // 3. Fetch Sublists
                // Wrap in try/catch to avoid blocking main content if permissions fail (e.g. public list but restrictive list-query rules)
                try {
                    const listsRef = collection(db, 'lists');
                    // Check if current user is owner to decide whether to show private sublists
                    // We need auth instance
                    const { getAuth } = await import('firebase/auth');
                    const auth = getAuth();
                    const currentUser = auth.currentUser;
                    const isOwner = currentUser && listData.userId === currentUser.uid;

                    let sublistsQ;
                    if (isOwner) {
                        sublistsQ = query(listsRef, where('parentListId', '==', listId));
                    } else {
                        // Non-owners can only see public sublists. 
                        // Note: This requires index on parentListId + isPublic usually, but let's try.
                        // If it fails with index error, it's better than permission error (and we catch it).
                        sublistsQ = query(listsRef, where('parentListId', '==', listId), where('isPublic', '==', true));
                    }

                    const sublistsSnap = await getDocs(sublistsQ);
                    const sublistsData = sublistsSnap.docs.map(d => ({ id: d.id, ...d.data() })) as ListEntity[];
                    setSublists(sublistsData);
                } catch (subErr: any) {
                    if (subErr.code === 'permission-denied') {
                        console.warn("Could not fetch sublists: Permission denied. (Private sublists hidden)");
                    } else if (subErr.code === 'failed-precondition') {
                        console.warn("Could not fetch sublists: Missing Index for parentListId + isPublic query.");
                    } else {
                        console.warn("Could not fetch sublists:", subErr);
                    }
                    setSublists([]);
                }

            } catch (err: any) {
                if (err.code === 'permission-denied') {
                    console.debug("Permission denied for list", listId); // Debug level
                    setError('private'); // Specific error code
                } else {
                    console.error("Error fetching list details:", err);
                    setError(err.message);
                }
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, [listId]);

    return { list, reviews, sublists, loading, error };
};

